#ifndef CPP_FUNDAMENTALS_ESTANTE_H
#define CPP_FUNDAMENTALS_ESTANTE_H

#include <string>

// Quantités permises : chacune entre 0 et 10, bornes incluses.
bool cantidades_validas(int pequenas, int grandes);
// Exigent des quantités valides.
int espacios_ocupados(int pequenas, int grandes);
std::string descripcion_carga(int pequenas, int grandes);

#endif

#include "estante.h"

bool cantidades_validas(int pequenas, int grandes) {
    return pequenas >= 0 && pequenas <= 10
        && grandes >= 0 && grandes <= 10;
}

int espacios_ocupados(int pequenas, int grandes) {
    return 2 * pequenas + 5 * grandes;
}

#include "estante.h"

std::string descripcion_carga(int pequenas, int grandes) {
    const int espacios{espacios_ocupados(pequenas, grandes)};
    if (espacios == 0) {
        return "Vide";
    }
    if (espacios <= 20) {
        return "Léger";
    }
    return "Lourd";
}

#include "estante.h"
#include <iostream>

int main() {
    const int pequenas{4};
    const int grandes{3};
    if (!cantidades_validas(pequenas, grandes)) {
        std::cout << "Quantités invalides\n";
        return 0;
    }
    std::cout << "Espaces : " << espacios_ocupados(pequenas, grandes) << '\n';
    std::cout << "Charge : " << descripcion_carga(pequenas, grandes) << '\n';
    return 0;
}

#include "estante.h"
#include <iostream>

int main() {
    std::cout << cantidades_validas(10, 0) << ' '
              << cantidades_validas(0, 11) << '\n';
    return 0;
}

#include "estante.h"
#include <iostream>

int main() {
    std::cout << espacios_ocupados(1, 2) << ' '
              << descripcion_carga(1, 2) << '\n';
    std::cout << espacios_ocupados(8, 1) << ' '
              << descripcion_carga(8, 1) << '\n';
    return 0;
}

